+CachedBlockTemplate BlockTemplateManager::RefreshCachedTemplate()
+{
+    AssertLockHeld(::cs_main);
+    CachedBlockTemplate& cache{m_cached_template};
+    const uint256 tip{CHECK_NONFATAL(m_chainman.ActiveChain().Tip())->GetBlockHash()};
